import os
from robot.result import ExecutionResult, ResultVisitor
from taf.ul.ettf.logger.logger import custom_logger
from taf.ul.ettf.utils.paths import get_robot_output_dir
from taf.ul.ettf.scheduler.base_listeners import GlobalListener

logger = custom_logger('FailingTestsRemover')


class _FailingTestsRemoverVisitor(ResultVisitor):
    def visit_suite(self, suite):
        def test_passed(test):
            if not test.passed:
                logger.warn('"{}" failed and will be removed from output.xml.'.format(test.name))
            return test.passed
        suite.tests = [test for test in suite.tests if test_passed(test)]


class FailingTestsRemover(GlobalListener):
    def __init__(self):
        super(FailingTestsRemover, self).__init__()
        self._output_xml = None
        logger.warn("Failing Tests Results Remover ENABLED")

    def start_suite(self, data, result):
        self._output_xml = os.path.join(get_robot_output_dir(), 'output.xml')

    def close(self):
        result = ExecutionResult(self._output_xml)
        result.visit(_FailingTestsRemoverVisitor())
        result.save()


failing_tests_remover = FailingTestsRemover
